57	static void openFileIfExists(const char * filename, std::optional<ReadBufferFromFilePRead> & out)
58	{
59	    /// Ignoring time of check is not time of use cases, as procfs/sysfs files are fairly persistent.
60	
61	    std::error_code ec;
62	    if (std::filesystem::is_regular_file(filename, ec))
63	        out.emplace(filename, small_buffer_size);
64	}
65	
66	static std::unique_ptr<ReadBufferFromFilePRead> openFileIfExists(const std::string & filename)
67	{
68	    std::error_code ec;
69	    if (std::filesystem::is_regular_file(filename, ec))
70	        return std::make_unique<ReadBufferFromFilePRead>(filename, small_buffer_size);
71	    return {};
72	}
