103	void AsynchronousMetrics::openSensors()
104	{
105	    LOG_TRACE(log, "Scanning /sys/class/thermal");
106	
107	    thermal.clear();
108	
109	    for (size_t thermal_device_index = 0;; ++thermal_device_index)
110	    {
111	        std::unique_ptr<ReadBufferFromFilePRead> file = openFileIfExists(fmt::format("/sys/class/thermal/thermal_zone{}/temp", thermal_device_index));
112	        if (!file)
113	        {
114	            /// Sometimes indices are from zero sometimes from one.
115	            if (thermal_device_index == 0)
116	                continue;
117	            else
118	                break;
119	        }
120	
121	        file->rewind();
122	        Int64 temperature = 0;
123	        try
124	        {
125	            readText(temperature, *file);
126	        }
127	        catch (const ErrnoException & e)
128	        {
129	            LOG_WARNING(
130	                &Poco::Logger::get("AsynchronousMetrics"),
131	                "Thermal monitor '{}' exists but could not be read, error {}.",
132	                thermal_device_index,
133	                e.getErrno());
134	            continue;
135	        }
136	
137	        thermal.emplace_back(std::move(file));
138	    }
139	}
