168	void AsynchronousMetrics::openEDAC()
169	{
170	    LOG_TRACE(log, "Scanning /sys/devices/system/edac");
171	
172	    edac.clear();
173	
174	    for (size_t edac_index = 0;; ++edac_index)
175	    {
176	        String edac_correctable_file = fmt::format("/sys/devices/system/edac/mc/mc{}/ce_count", edac_index);
177	        String edac_uncorrectable_file = fmt::format("/sys/devices/system/edac/mc/mc{}/ue_count", edac_index);
178	
179	        bool edac_correctable_file_exists = std::filesystem::exists(edac_correctable_file);
180	        bool edac_uncorrectable_file_exists = std::filesystem::exists(edac_uncorrectable_file);
181	
182	        if (!edac_correctable_file_exists && !edac_uncorrectable_file_exists)
183	        {
184	            if (edac_index == 0)
185	                continue;
186	            else
187	                break;
188	        }
189	
190	        edac.emplace_back();
191	
192	        if (edac_correctable_file_exists)
193	            edac.back().first = openFileIfExists(edac_correctable_file);
194	        if (edac_uncorrectable_file_exists)
195	            edac.back().second = openFileIfExists(edac_uncorrectable_file);
196	    }
197	}
