199	void AsynchronousMetrics::openSensorsChips()
200	{
201	    LOG_TRACE(log, "Scanning /sys/class/hwmon");
202	
203	    hwmon_devices.clear();
204	
205	    for (size_t hwmon_index = 0;; ++hwmon_index)
206	    {
207	        String hwmon_name_file = fmt::format("/sys/class/hwmon/hwmon{}/name", hwmon_index);
208	        if (!std::filesystem::exists(hwmon_name_file))
209	        {
210	            if (hwmon_index == 0)
211	                continue;
212	            else
213	                break;
214	        }
215	
216	        String hwmon_name;
217	        ReadBufferFromFilePRead hwmon_name_in(hwmon_name_file, small_buffer_size);
218	        readText(hwmon_name, hwmon_name_in);
219	        std::replace(hwmon_name.begin(), hwmon_name.end(), ' ', '_');
220	
221	        for (size_t sensor_index = 0;; ++sensor_index)
222	        {
223	            String sensor_name_file = fmt::format("/sys/class/hwmon/hwmon{}/temp{}_label", hwmon_index, sensor_index);
224	            String sensor_value_file = fmt::format("/sys/class/hwmon/hwmon{}/temp{}_input", hwmon_index, sensor_index);
225	
226	            bool sensor_name_file_exists = std::filesystem::exists(sensor_name_file);
227	            bool sensor_value_file_exists = std::filesystem::exists(sensor_value_file);
228	
229	            /// Sometimes there are labels but there is no files with data or vice versa.
230	            if (!sensor_name_file_exists && !sensor_value_file_exists)
231	            {
232	                if (sensor_index == 0)
233	                    continue;
234	                else
235	                    break;
236	            }
237	
238	            std::unique_ptr<ReadBufferFromFilePRead> file = openFileIfExists(sensor_value_file);
239	            if (!file)
240	                continue;
241	
242	            String sensor_name;
243	            if (sensor_name_file_exists)
244	            {
245	                ReadBufferFromFilePRead sensor_name_in(sensor_name_file, small_buffer_size);
246	                readText(sensor_name, sensor_name_in);
247	                std::replace(sensor_name.begin(), sensor_name.end(), ' ', '_');
248	            }
249	
250	            file->rewind();
251	            Int64 temperature = 0;
252	            try
253	            {
254	                readText(temperature, *file);
255	            }
256	            catch (const ErrnoException & e)
257	            {
258	                LOG_WARNING(
259	                    &Poco::Logger::get("AsynchronousMetrics"),
260	                    "Hardware monitor '{}', sensor '{}' exists but could not be read, error {}.",
261	                    hwmon_name,
262	                    sensor_name,
263	                    e.getErrno());
264	                continue;
265	            }
266	
267	            hwmon_devices[hwmon_name][sensor_name] = std::move(file);
268	        }
269	    }
270	}
