273	void AsynchronousMetrics::start()
274	{
275	    /// Update once right now, to make metrics available just after server start
276	    /// (without waiting for asynchronous_metrics_update_period_s).
277	    update(std::chrono::system_clock::now());
278	    thread = std::make_unique<ThreadFromGlobalPool>([this] { run(); });
279	}
