281	void AsynchronousMetrics::stop()
282	{
283	    try
284	    {
285	        {
286	            std::lock_guard lock{mutex};
287	            quit = true;
288	        }
289	
290	        wait_cond.notify_one();
291	        if (thread)
292	        {
293	            thread->join();
294	            thread.reset();
295	        }
296	    }
297	    catch (...)
298	    {
299	        DB::tryLogCurrentException(__PRETTY_FUNCTION__);
300	    }
301	}
