426	void AsynchronousMetrics::ProcStatValuesCPU::read(ReadBuffer & in)
427	{
428	    readText(user, in);
429	    skipWhitespaceIfAny(in, true);
430	    readText(nice, in);
431	    skipWhitespaceIfAny(in, true);
432	    readText(system, in);
433	    skipWhitespaceIfAny(in, true);
434	    readText(idle, in);
435	    skipWhitespaceIfAny(in, true);
436	    readText(iowait, in);
437	    skipWhitespaceIfAny(in, true);
438	    readText(irq, in);
439	    skipWhitespaceIfAny(in, true);
440	    readText(softirq, in);
441	
442	    /// Just in case for old Linux kernels, we check if these values present.
443	
444	    if (!checkChar('\n', in))
445	    {
446	        skipWhitespaceIfAny(in, true);
447	        readText(steal, in);
448	    }
449	
450	    if (!checkChar('\n', in))
451	    {
452	        skipWhitespaceIfAny(in, true);
453	        readText(guest, in);
454	    }
455	
456	    if (!checkChar('\n', in))
457	    {
458	        skipWhitespaceIfAny(in, true);
459	        readText(guest_nice, in);
460	    }
461	
462	    skipToNextLineOrEOF(in);
463	}
