466	AsynchronousMetrics::ProcStatValuesCPU::operator-(const AsynchronousMetrics::ProcStatValuesCPU & other) const
467	{
468	    ProcStatValuesCPU res{};
469	    res.user = user - other.user;
470	    res.nice = nice - other.nice;
