566	void AsynchronousMetrics::update(std::chrono::system_clock::time_point update_time)
567	{
568	    Stopwatch watch;
569	
570	    AsynchronousMetricValues new_values;
571	
572	    auto current_time = std::chrono::system_clock::now();
573	    auto time_after_previous_update [[maybe_unused]] = current_time - previous_update_time;
574	    previous_update_time = update_time;
575	
576	    /// This is also a good indicator of system responsiveness.
577	    new_values["Jitter"] = std::chrono::duration_cast<std::chrono::nanoseconds>(current_time - update_time).count() / 1e9;
578	
579	    {
580	        if (auto mark_cache = getContext()->getMarkCache())
581	        {
582	            new_values["MarkCacheBytes"] = mark_cache->weight();
583	            new_values["MarkCacheFiles"] = mark_cache->count();
584	        }
585	    }
586	
587	    {
588	        if (auto uncompressed_cache = getContext()->getUncompressedCache())
589	        {
590	            new_values["UncompressedCacheBytes"] = uncompressed_cache->weight();
591	            new_values["UncompressedCacheCells"] = uncompressed_cache->count();
592	        }
593	    }
594	
595	    {
596	        if (auto index_mark_cache = getContext()->getIndexMarkCache())
597	        {
598	            new_values["IndexMarkCacheBytes"] = index_mark_cache->weight();
599	            new_values["IndexMarkCacheFiles"] = index_mark_cache->count();
600	        }
601	    }
602	
603	    {
604	        if (auto index_uncompressed_cache = getContext()->getIndexUncompressedCache())
605	        {
606	            new_values["IndexUncompressedCacheBytes"] = index_uncompressed_cache->weight();
607	            new_values["IndexUncompressedCacheCells"] = index_uncompressed_cache->count();
608	        }
609	    }
610	
611	    {
612	        if (auto mmap_cache = getContext()->getMMappedFileCache())
613	        {
614	            new_values["MMapCacheCells"] = mmap_cache->count();
615	        }
616	    }
617	
618	    {
619	        auto caches = FileCacheFactory::instance().getAll();
620	        for (const auto & [_, cache_data] : caches)
621	        {
622	            new_values["FilesystemCacheBytes"] = cache_data->cache->getUsedCacheSize();
623	            new_values["FilesystemCacheFiles"] = cache_data->cache->getFileSegmentsNum();
624	        }
625	    }
626	
627	#if USE_ROCKSDB
628	    {
629	        if (auto metadata_cache = getContext()->tryGetMergeTreeMetadataCache())
630	        {
631	            new_values["MergeTreeMetadataCacheSize"] = metadata_cache->getEstimateNumKeys();
632	        }
633	    }
634	#endif
635	
636	#if USE_EMBEDDED_COMPILER
637	    {
638	        if (auto * compiled_expression_cache = CompiledExpressionCacheFactory::instance().tryGetCache())
639	        {
640	            new_values["CompiledExpressionCacheBytes"] = compiled_expression_cache->weight();
641	            new_values["CompiledExpressionCacheCount"]  = compiled_expression_cache->count();
642	        }
643	    }
644	#endif
645	
646	
647	    new_values["Uptime"] = getContext()->getUptimeSeconds();
648	
649	    {
650	        if (const auto stats = getHashTablesCacheStatistics())
651	        {
652	            new_values["HashTableStatsCacheEntries"] = stats->entries;
653	            new_values["HashTableStatsCacheHits"] = stats->hits;
654	            new_values["HashTableStatsCacheMisses"] = stats->misses;
655	        }
656	    }
657	
658	    /// Process process memory usage according to OS
659	#if defined(OS_LINUX) || defined(OS_FREEBSD)
660	    {
661	        MemoryStatisticsOS::Data data = memory_stat.get();
662	
663	        new_values["MemoryVirtual"] = data.virt;
664	        new_values["MemoryResident"] = data.resident;
665	#if !defined(OS_FREEBSD)
666	        new_values["MemoryShared"] = data.shared;
667	#endif
668	        new_values["MemoryCode"] = data.code;
669	        new_values["MemoryDataAndStack"] = data.data_and_stack;
670	
671	        /// We must update the value of total_memory_tracker periodically.
672	        /// Otherwise it might be calculated incorrectly - it can include a "drift" of memory amount.
673	        /// See https://github.com/ClickHouse/ClickHouse/issues/10293
674	        {
675	            Int64 amount = total_memory_tracker.get();
676	            Int64 peak = total_memory_tracker.getPeak();
677	            Int64 new_amount = data.resident;
678	
679	            Int64 difference = new_amount - amount;
680	
681	            /// Log only if difference is high. This is for convenience. The threshold is arbitrary.
682	            if (difference >= 1048576 || difference <= -1048576)
683	                LOG_TRACE(log,
684	                    "MemoryTracking: was {}, peak {}, will set to {} (RSS), difference: {}",
685	                    ReadableSize(amount),
686	                    ReadableSize(peak),
687	                    ReadableSize(new_amount),
688	                    ReadableSize(difference));
689	
690	            total_memory_tracker.set(new_amount);
691	            CurrentMetrics::set(CurrentMetrics::MemoryTracking, new_amount);
692	        }
693	    }
694	#endif
695	
696	#if defined(OS_LINUX)
697	    if (loadavg)
698	    {
699	        try
700	        {
701	            loadavg->rewind();
702	
703	            Float64 loadavg1 = 0;
704	            Float64 loadavg5 = 0;
705	            Float64 loadavg15 = 0;
706	            UInt64 threads_runnable = 0;
707	            UInt64 threads_total = 0;
708	
709	            readText(loadavg1, *loadavg);
710	            skipWhitespaceIfAny(*loadavg);
711	            readText(loadavg5, *loadavg);
712	            skipWhitespaceIfAny(*loadavg);
713	            readText(loadavg15, *loadavg);
714	            skipWhitespaceIfAny(*loadavg);
715	            readText(threads_runnable, *loadavg);
716	            assertChar('/', *loadavg);
717	            readText(threads_total, *loadavg);
718	
719	            new_values["LoadAverage1"] = loadavg1;
720	            new_values["LoadAverage5"] = loadavg5;
721	            new_values["LoadAverage15"] = loadavg15;
722	            new_values["OSThreadsRunnable"] = threads_runnable;
723	            new_values["OSThreadsTotal"] = threads_total;
724	        }
725	        catch (...)
726	        {
727	            tryLogCurrentException(__PRETTY_FUNCTION__);
728	        }
729	    }
730	
731	    if (uptime)
732	    {
733	        try
734	        {
735	            uptime->rewind();
736	
737	            Float64 uptime_seconds = 0;
738	            readText(uptime_seconds, *uptime);
739	
740	            new_values["OSUptime"] = uptime_seconds;
741	        }
742	        catch (...)
743	        {
744	            tryLogCurrentException(__PRETTY_FUNCTION__);
745	        }
746	    }
747	
748	    if (proc_stat)
749	    {
750	        try
751	        {
752	            proc_stat->rewind();
753	
754	            int64_t hz = sysconf(_SC_CLK_TCK);
755	            if (-1 == hz)
756	                throwFromErrno("Cannot call 'sysconf' to obtain system HZ", ErrorCodes::CANNOT_SYSCONF);
757	
758	            double multiplier = 1.0 / hz / (std::chrono::duration_cast<std::chrono::nanoseconds>(time_after_previous_update).count() / 1e9);
759	            size_t num_cpus = 0;
760	
761	            ProcStatValuesOther current_other_values{};
762	            ProcStatValuesCPU delta_values_all_cpus{};
763	
764	            while (!proc_stat->eof())
765	            {
766	                String name;
767	                readStringUntilWhitespace(name, *proc_stat);
768	                skipWhitespaceIfAny(*proc_stat);
769	
770	                if (name.starts_with("cpu"))
771	                {
772	                    String cpu_num_str = name.substr(strlen("cpu"));
773	                    UInt64 cpu_num = 0;
774	                    if (!cpu_num_str.empty())
775	                    {
776	                        cpu_num = parse<UInt64>(cpu_num_str);
777	
778	                        if (cpu_num > 1000000) /// Safety check, arbitrary large number, suitable for supercomputing applications.
779	                            throw Exception(ErrorCodes::CORRUPTED_DATA, "Too many CPUs (at least {}) in '/proc/stat' file", cpu_num);
780	
781	                        if (proc_stat_values_per_cpu.size() <= cpu_num)
782	                            proc_stat_values_per_cpu.resize(cpu_num + 1);
783	                    }
784	
785	                    ProcStatValuesCPU current_values{};
786	                    current_values.read(*proc_stat);
787	
788	                    ProcStatValuesCPU & prev_values = !cpu_num_str.empty() ? proc_stat_values_per_cpu[cpu_num] : proc_stat_values_all_cpus;
789	
790	                    if (!first_run)
791	                    {
792	                        ProcStatValuesCPU delta_values = current_values - prev_values;
793	
794	                        String cpu_suffix;
795	                        if (!cpu_num_str.empty())
796	                        {
797	                            cpu_suffix = "CPU" + cpu_num_str;
798	                            ++num_cpus;
799	                        }
800	                        else
801	                            delta_values_all_cpus = delta_values;
802	
803	                        new_values["OSUserTime" + cpu_suffix] = delta_values.user * multiplier;
804	                        new_values["OSNiceTime" + cpu_suffix] = delta_values.nice * multiplier;
805	                        new_values["OSSystemTime" + cpu_suffix] = delta_values.system * multiplier;
806	                        new_values["OSIdleTime" + cpu_suffix] = delta_values.idle * multiplier;
807	                        new_values["OSIOWaitTime" + cpu_suffix] = delta_values.iowait * multiplier;
808	                        new_values["OSIrqTime" + cpu_suffix] = delta_values.irq * multiplier;
809	                        new_values["OSSoftIrqTime" + cpu_suffix] = delta_values.softirq * multiplier;
810	                        new_values["OSStealTime" + cpu_suffix] = delta_values.steal * multiplier;
811	                        new_values["OSGuestTime" + cpu_suffix] = delta_values.guest * multiplier;
812	                        new_values["OSGuestNiceTime" + cpu_suffix] = delta_values.guest_nice * multiplier;
813	                    }
814	
815	                    prev_values = current_values;
816	                }
817	                else if (name == "intr")
818	                {
819	                    readText(current_other_values.interrupts, *proc_stat);
820	                    skipToNextLineOrEOF(*proc_stat);
821	                }
822	                else if (name == "ctxt")
823	                {
824	                    readText(current_other_values.context_switches, *proc_stat);
825	                    skipToNextLineOrEOF(*proc_stat);
826	                }
827	                else if (name == "processes")
828	                {
829	                    readText(current_other_values.processes_created, *proc_stat);
830	                    skipToNextLineOrEOF(*proc_stat);
831	                }
832	                else if (name == "procs_running")
833	                {
834	                    UInt64 processes_running = 0;
835	                    readText(processes_running, *proc_stat);
836	                    skipToNextLineOrEOF(*proc_stat);
837	                    new_values["OSProcessesRunning"] = processes_running;
838	                }
839	                else if (name == "procs_blocked")
840	                {
841	                    UInt64 processes_blocked = 0;
842	                    readText(processes_blocked, *proc_stat);
843	                    skipToNextLineOrEOF(*proc_stat);
844	                    new_values["OSProcessesBlocked"] = processes_blocked;
845	                }
846	                else
847	                    skipToNextLineOrEOF(*proc_stat);
848	            }
849	
850	            if (!first_run)
851	            {
852	                ProcStatValuesOther delta_values = current_other_values - proc_stat_values_other;
853	
854	                new_values["OSInterrupts"] = delta_values.interrupts;
855	                new_values["OSContextSwitches"] = delta_values.context_switches;
856	                new_values["OSProcessesCreated"] = delta_values.processes_created;
857	
858	                /// Also write values normalized to 0..1 by diving to the number of CPUs.
859	                /// These values are good to be averaged across the cluster of non-uniform servers.
860	
861	                if (num_cpus)
862	                {
863	                    new_values["OSUserTimeNormalized"] = delta_values_all_cpus.user * multiplier / num_cpus;
864	                    new_values["OSNiceTimeNormalized"] = delta_values_all_cpus.nice * multiplier / num_cpus;
865	                    new_values["OSSystemTimeNormalized"] = delta_values_all_cpus.system * multiplier / num_cpus;
866	                    new_values["OSIdleTimeNormalized"] = delta_values_all_cpus.idle * multiplier / num_cpus;
867	                    new_values["OSIOWaitTimeNormalized"] = delta_values_all_cpus.iowait * multiplier / num_cpus;
868	                    new_values["OSIrqTimeNormalized"] = delta_values_all_cpus.irq * multiplier / num_cpus;
869	                    new_values["OSSoftIrqTimeNormalized"] = delta_values_all_cpus.softirq * multiplier / num_cpus;
870	                    new_values["OSStealTimeNormalized"] = delta_values_all_cpus.steal * multiplier / num_cpus;
871	                    new_values["OSGuestTimeNormalized"] = delta_values_all_cpus.guest * multiplier / num_cpus;
872	                    new_values["OSGuestNiceTimeNormalized"] = delta_values_all_cpus.guest_nice * multiplier / num_cpus;
873	                }
874	            }
875	
876	            proc_stat_values_other = current_other_values;
877	        }
878	        catch (...)
879	        {
880	            tryLogCurrentException(__PRETTY_FUNCTION__);
881	        }
882	    }
883	
884	    if (meminfo)
885	    {
886	        try
887	        {
888	            meminfo->rewind();
889	
890	            uint64_t free_plus_cached_bytes = 0;
891	
892	            while (!meminfo->eof())
893	            {
894	                String name;
895	                readStringUntilWhitespace(name, *meminfo);
896	                skipWhitespaceIfAny(*meminfo, true);
897	
898	                uint64_t kb = 0;
899	                readText(kb, *meminfo);
900	
901	                if (!kb)
902	                {
903	                    skipToNextLineOrEOF(*meminfo);
904	                    continue;
905	                }
906	
907	                skipWhitespaceIfAny(*meminfo, true);
908	
909	                /**
910	                 * Not all entries in /proc/meminfo contain the kB suffix, e.g.
911	                 * HugePages_Total:       0
912	                 * HugePages_Free:        0
913	                 * We simply skip such entries as they're not needed
914	                 */
915	                if (*meminfo->position() == '\n')
916	                {
917	                    skipToNextLineOrEOF(*meminfo);
918	                    continue;
919	                }
920	
921	                assertString("kB", *meminfo);
922	
923	                uint64_t bytes = kb * 1024;
924	
925	                if (name == "MemTotal:")
926	                {
927	                    new_values["OSMemoryTotal"] = bytes;
928	                }
929	                else if (name == "MemFree:")
930	                {
931	                    /// We cannot simply name this metric "Free", because it confuses users.
932	                    /// See https://www.linuxatemyram.com/
933	                    /// For convenience we also provide OSMemoryFreePlusCached, that should be somewhat similar to OSMemoryAvailable.
934	
935	                    free_plus_cached_bytes += bytes;
936	                    new_values["OSMemoryFreeWithoutCached"] = bytes;
937	                }
938	                else if (name == "MemAvailable:")
939	                {
940	                    new_values["OSMemoryAvailable"] = bytes;
941	                }
942	                else if (name == "Buffers:")
943	                {
944	                    new_values["OSMemoryBuffers"] = bytes;
945	                }
946	                else if (name == "Cached:")
947	                {
948	                    free_plus_cached_bytes += bytes;
949	                    new_values["OSMemoryCached"] = bytes;
950	                }
951	                else if (name == "SwapCached:")
952	                {
953	                    new_values["OSMemorySwapCached"] = bytes;
954	                }
955	
956	                skipToNextLineOrEOF(*meminfo);
957	            }
958	
959	            new_values["OSMemoryFreePlusCached"] = free_plus_cached_bytes;
960	        }
961	        catch (...)
962	        {
963	            tryLogCurrentException(__PRETTY_FUNCTION__);
964	        }
965	    }
966	
967	    // Try to add processor frequencies, ignoring errors.
968	    if (cpuinfo)
969	    {
970	        try
971	        {
972	            cpuinfo->rewind();
973	
974	            // We need the following lines:
975	            // processor : 4
976	            // cpu MHz : 4052.941
977	            // They contain tabs and are interspersed with other info.
978	
979	            int core_id = 0;
980	            while (!cpuinfo->eof())
981	            {
982	                std::string s;
983	                // We don't have any backslash escape sequences in /proc/cpuinfo, so
984	                // this function will read the line until EOL, which is exactly what
985	                // we need.
986	                readEscapedStringUntilEOL(s, *cpuinfo);
987	                // It doesn't read the EOL itself.
988	                ++cpuinfo->position();
989	
990	                if (s.rfind("processor", 0) == 0)
991	                {
992	                    /// s390x example: processor 0: version = FF, identification = 039C88, machine = 3906
993	                    /// non s390x example: processor : 0
994	                    if (auto colon = s.find_first_of(':'))
995	                    {
996	#ifdef __s390x__
997	                        core_id = std::stoi(s.substr(10)); /// 10: length of "processor" plus 1
998	#else
999	                        core_id = std::stoi(s.substr(colon + 2));
1000	#endif
1001	                    }
1002	                }
1003	                else if (s.rfind("cpu MHz", 0) == 0)
1004	                {
1005	                    if (auto colon = s.find_first_of(':'))
1006	                    {
1007	                        auto mhz = std::stod(s.substr(colon + 2));
1008	                        new_values[fmt::format("CPUFrequencyMHz_{}", core_id)] = mhz;
1009	                    }
1010	                }
1011	            }
1012	        }
1013	        catch (...)
1014	        {
1015	            tryLogCurrentException(__PRETTY_FUNCTION__);
1016	        }
1017	    }
1018	
1019	    if (file_nr)
1020	    {
1021	        try
1022	        {
1023	            file_nr->rewind();
1024	
1025	            uint64_t open_files = 0;
1026	            readText(open_files, *file_nr);
1027	            new_values["OSOpenFiles"] = open_files;
1028	        }
1029	        catch (...)
1030	        {
1031	            tryLogCurrentException(__PRETTY_FUNCTION__);
1032	        }
1033	    }
1034	
1035	    /// Update list of block devices periodically
1036	    /// (i.e. someone may add new disk to RAID array)
1037	    if (block_devices_rescan_delay.elapsedSeconds() >= 300)
1038	        openBlockDevices();
1039	
1040	    try
1041	    {
1042	        for (auto & [name, device] : block_devs)
1043	        {
1044	            device->rewind();
1045	
1046	            BlockDeviceStatValues current_values{};
1047	            BlockDeviceStatValues & prev_values = block_device_stats[name];
1048	            current_values.read(*device);
1049	
1050	            BlockDeviceStatValues delta_values = current_values - prev_values;
1051	            prev_values = current_values;
1052	
1053	            if (first_run)
1054	                continue;
1055	
1056	            /// Always 512 according to the docs.
