1058	
1059	            /// Always in milliseconds according to the docs.
1060	            static constexpr double time_multiplier = 1e-6;
1061	
1062	            new_values["BlockReadOps_" + name] = delta_values.read_ios;
1063	            new_values["BlockWriteOps_" + name] = delta_values.write_ios;
1064	            new_values["BlockDiscardOps_" + name] = delta_values.discard_ops;
1065	
1066	            new_values["BlockReadMerges_" + name] = delta_values.read_merges;
1067	            new_values["BlockWriteMerges_" + name] = delta_values.write_merges;
